programs.haiku:
"""Layer 15 MLP down-projection, hidden unit 4544: a "conclusion just drawn" detector.

What it responds to, in plain terms: a word that states a logical consequence in an
argument or derivation.
  * "So", "Thus", "Therefore", "Hence" that open a sentence or follow a comma: strong.
  * the arrows "⇒", "⟹", "→": strong.
  * "then", "implies", "means", "gives", "becomes", "requires", and "so" in the middle
    of a sentence: weak.
  * a comma in a sentence that opened with "Since", "Because", "If", "As", "Given" or
    "When" (a premise, after which a conclusion is expected): a little; a comma in a
    sentence that opened with "Therefore", "Thus", "So" or "Hence": more.
The response fades: it halves with every later token, and is gone after eight tokens.
Everywhere else the component is near zero.

The program keeps a small state across tokens: how many tokens ago the last
conclusion word was and how strong it was, and the first word of the current clause.
It resets at each new document. Its prediction is the faded strength of the latest
conclusion, plus the comma terms.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

# strong when they open a sentence or follow a comma
STRONG_WORDS = {"so", "thus", "therefore", "hence"}
ARROWS = {"⇒", "⟹", "→"}
WEAK_WORDS = {
    "then", "implies", "means", "gives", "becomes", "requires", "so", "thus", "therefore", "hence",
}
PREMISE_OPENERS = {"since", "because", "as", "given", "if", "when"}
CONCLUSION_OPENERS = {"so", "thus", "therefore", "hence"}

STRONG, ARROW, WEAK = 2.4, 2.0, 0.7  # mean activation of each kind of conclusion word
PREMISE_COMMA, CONCLUSION_COMMA = 0.4, 0.6
HALF_LIFE = 0.5  # the response halves per token
WINDOW = 8  # tokens after a conclusion word within which it still responds


def _opens_sentence(previous: str) -> bool:
    """True when the previous token ends a sentence, a clause or a line, or starts the text."""
    return previous == "" or previous.strip()[-1:] in {",", ":", ".", "!", "?"} or "\n" in previous


def step(carry, prefix, upstream: Mapping):
    # carry: None, or a dict with the document id, tokens since the last conclusion word
    # (None if none in this document), that word's strength, and the current clause's first word
    if carry is None or carry["doc"] != prefix.document_ids[-1]:
        carry = {"doc": prefix.document_ids[-1], "since": None, "strength": 0.0, "clause": ""}
    else:
        carry = dict(carry)
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    new_doc = len(prefix.document_ids) == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]
    previous = "" if new_doc else prefix.token_strings[-2]

    # 1. Does this token state a conclusion?
    strength = 0.0
    if word in STRONG_WORDS and _opens_sentence(previous):
        strength = STRONG
    elif word in ARROWS:
        strength = ARROW
    elif word in WEAK_WORDS:
        strength = WEAK
    if strength > 0:
        carry["since"], carry["strength"] = 0, strength
    elif carry["since"] is not None:
        carry["since"] += 1

    # 2. The faded response to the latest conclusion word
    value = 0.0
    if carry["since"] is not None and carry["since"] <= WINDOW:
        value = carry["strength"] * HALF_LIFE ** carry["since"]

    # 3. Commas closing a premise, or following an opening conclusion word
    if token.strip() in {",", ":"}:
        if carry["clause"] in PREMISE_OPENERS:
            value += PREMISE_COMMA
        if carry["clause"] in CONCLUSION_OPENERS:
            value += CONCLUSION_COMMA

    # 4. Track the current sentence's first word; a sentence ends at . ! ? or a line break
    if any(mark in token for mark in ".!?\n"):
        carry["clause"] = ""
    elif word and not carry["clause"]:
        carry["clause"] = word
    return carry, value

"""Initial-value and expectation detector (layer 15 MLP output, component 4553).

What it responds to, in plain terms:
1. An '=' (or ':' in a state object) that sets a variable's starting value in code,
   e.g. `int res = -1;`, `self.game_over = False`, `isLoading: 0`. Assignments in
   code declarations are strongest; '=' in prose (maths) is weak.
2. A word that sets up an expectation, belief or default ("thought", "supposed",
   "believed", "seemed", "originally", "initially", "default", ...), and the words
   that follow it ("supposed [to] be", "thought [it] [was]", "believed [to] [be]").

"already" (as in "already using") pushes the prediction slightly negative.
Everything else is predicted as zero. These cues explain only about 1-2% of the
component's variance: most of its activity is diffuse and not captured by any
short list of words.
"""

READS = ()

DECL_WORDS = {"int", "bool", "float", "double", "long", "char", "var", "let", "const",
              "String", "static", "private", "public", "final", "auto", "def", "val"}

CUE_WORDS = {"thought", "think", "thinks", "supposed", "supposedly", "believed", "believe",
             "seemed", "seem", "seems", "seemingly", "expected", "expect", "assumed",
             "originally", "initially", "normally", "usually", "previously", "formerly",
             "default", "DEFAULT", "considered", "regarded", "seen", "wanted", "planned"}

FOLLOW_WORDS = {"to", "be", "was", "as", "been", "would", "have", "had", "like", "the", "is"}

ASSIGN = {"=", ":="}


def step(carry, prefix, upstream):
    # carry: (line has a declaration word, tokens since the last cue word, document id)
    if carry is None or prefix.document_ids[-1] != carry[2]:
        line_decl, since_cue = False, 99
    else:
        line_decl, since_cue = carry[0], carry[1]
    tok = prefix.token_strings[-1]
    word = tok.strip()
    if "\n" in tok:
        line_decl = False
    if word in DECL_WORDS:
        line_decl = True

    value = -1.0 if word == "already" else 0.0
    if word in ASSIGN:
        value = 1.1 if line_decl else 0.4
    elif word == ":" and line_decl:
        value = 0.2

    if word in CUE_WORDS:
        value = max(value, 0.66)
        since_cue = 0
    else:
        since_cue += 1
        if since_cue <= 3:
            near = {1: 0.3, 2: 0.15, 3: 0.05}[since_cue]
            if word in FOLLOW_WORDS:
                near = max(near, 0.4)
            value = max(value, near)
    return (line_decl, since_cue, prefix.document_ids[-1]), value

"""Layer-15 MLP unit 4579 (its down_proj component): a 'means, purpose, cause or result is
coming' detector.

The unit is positive on the words that set up a means, purpose, cause or result phrase:
- Japanese and Korean postpositions for means, cause, place or manner (で, に, から, ため, ので,
  として, によって, 로, 으로, 에서): the strongest, about 7 on average.
- result connectives (so, therefore, thus, hence): about 3.
- relative 'which, where, when': about 2.
- causal or enabling verbs (lead, cause, allow, make, means, gives): about 2.
- 'to' that starts a purpose or means phrase, after 'used', 'led', 'lead', 'allow', 'make'
  ('used to determine', 'led to'): about 4.5. Other 'to' is about 0.7, and 'to' after complement
  or prepositional words ('need to', 'according to', 'close to') is about 0.
- 'for' after a use word ('used for'): about 4.
Everything else is about 0. The per-word values are the group averages measured on sampled text.
"""

READS = ()

JP_KR_POSTPOSITIONS = {
    "で", "での", "では", "に", "には", "にも", "でも", "から", "からの", "ため", "ので", "として",
    "によって", "により", "への", "へ", "에", "에서", "로", "으로", "로서", "中", "中的",
}
RESULT = {" so", " So", "So", " therefore", " Therefore", "Therefore", " thus", " Thus", "Thus",
          " hence", " Hence", " accordingly", " Accordingly"}
RELATIVES = {" which", " where", " when"}
CAUSE_VERBS = {" allows", " allow", " allowed", " lead", " leads", " led", " leading", " cause",
               " causes", " caused", " makes", " make", " gives", " means", " implies", " enables", " enable"}
USE_WORDS = {" used", " use", " uses", " using", " based", " related", "-based", "-related"}
COMPLEMENT_OR_PREP = {" need", " needs", " needed", " tend", " tends", " try", " tries", " ask",
                      " asked", " want", " seem", " seems", " continue", " continued", " get",
                      " known", " believed", " permitted", " according", " close", " due", " prior",
                      " similar", " next", " relative", " from"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    if cur in JP_KR_POSTPOSITIONS:
        return carry, 7.0
    if cur == " to":
        if prev in USE_WORDS or prev in CAUSE_VERBS:
            return carry, 4.5
        if prev in COMPLEMENT_OR_PREP:
            return carry, 0.0
        return carry, 0.7
    if cur == " for" and prev in USE_WORDS:
        return carry, 4.0
    if cur in RESULT:
        return carry, 3.3
    if cur in RELATIVES:
        return carry, 2.0
    if cur in CAUSE_VERBS:
        return carry, 2.3
    if cur in USE_WORDS:
        return carry, 1.5
    return carry, 0.0

"""Negation and exclusion words, for layers.15.mlp.down_proj component 4584.

This component goes negative where the text negates something. Its activation is
most negative on the negation word itself:
  - heavy negators, the strongest: "non", "without", "sans", "ohne", "без", "非"
    (about -4);
  - ordinary negators: "not", " no", "never", "nothing", "cannot", "n't", "nor", and
    their translations (about -3);
  - weaker negative forms: capitalised "No", "NOT", lowercase "no" (about -1.5).
It is moderately negative on disjunction words ("or", "Alternatively", "oder",
"ou", "или", "或", about -2), and weakly negative on exclusion and comparison
words ("less", "than", "un-", "low", "outside", "beyond", "else", about -1).
The word right after a negation word, when it is not punctuation, is also a
little negative (about -1): that is where the negation's scope begins.
Everywhere else the component is near zero.

The program looks each token up in these word lists and returns its value. Its
one piece of state is whether the previous word was a negation, reset at each
new document.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

HEAVY_NEGATION = {
    " non", " Non", "non", "Non", " without", " Without", "without", "Without",
    " sans", " ohne", " без", " bez", "非",
}
NEGATION = {
    " not", " Not", "not", "Not", " no", " never", " nothing", " none",
    " cannot", " nor", " нет", " не", " nicht", " nie", " ne", " pas", " não",
    " không", "不", "没", "没有", "无", "未", "無", "不是", "不会", "不要",
    "不需要", "'t", "’t",
}
WEAK_NEGATION = {" No", "No", "no", " NOT"}
DISJUNCTION = {
    " or", " Or", " OR", " Alternatively", "Alternatively", " oder", " ou", " или", "或",
}
EXCLUSION = {" less", " than", " un", " low", " outside", " beyond", " else", " regardless",
             " necessarily", "or"}
PUNCTUATION = set(".,;:!?()[]{}\n\"'")

HEAVY, NORMAL, WEAK = -4.0, -3.0, -1.5
DISJUNCTIVE, EXCLUDING, SCOPE = -2.0, -1.0, -1.0


def step(carry, prefix, upstream: Mapping):
    """The activation at this position: a negative number on negation and exclusion words."""
    new_document = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    after_negation = bool(carry) and not new_document
    word = prefix.token_strings[-1]
    if word in HEAVY_NEGATION:
        value, negation = HEAVY, True
    elif word in NEGATION:
        value, negation = NORMAL, True
    elif word in WEAK_NEGATION:
        value, negation = WEAK, True
    elif word in DISJUNCTION:
        value, negation = DISJUNCTIVE, False
    elif word in EXCLUSION:
        value, negation = EXCLUDING, False
    elif after_negation and word.strip() and word not in PUNCTUATION:
        value, negation = SCOPE, False
    else:
        value, negation = 0.0, False
    return negation, value
